# =============================================================================
# Semáforo na Prática · ficha de programação
# Monta a ficha no formato da planilha de programação semafórica da AMC/CTAFOR:
# cabeçalho (horários de entrada dos planos e estágios), planos e rodapé
# (links, tabela de entreverdes, verdes mínimos e ciclo máximo).
# =============================================================================

# Converte os planos calculados pelo app numa ficha com a mesma estrutura de ficha_1188.
ficha_do_app <- function(cruz, planos, ciclo_max = 120) {
  est <- cruz$estagios
  g <- cruz$grupos
  link_estagio <- sapply(est$estagio[est$tipo == "veicular"], function(e) paste(g$grupo[g$estagio == e], collapse = "/"))
  planos_f <- lapply(planos, function(p) {
    e <- p$estagios
    v <- e[e$tipo == "veicular", ]
    plano <- list(
      plano = p$plano, ciclo = p$ciclo,
      links = data.frame(link = link_estagio, verde = v$verde, amarelo = v$amarelo,
                         vermelho_geral = v$vermelho_geral,
                         vermelho = p$ciclo - v$verde - v$amarelo - v$vermelho_geral),
      instantes = setNames(e$inicio, paste0("F", e$estagio)))
    if (any(e$tipo == "pedestre")) {
      pe <- e[e$tipo == "pedestre", ]
      plano$pedestres <- data.frame(link = "P1/P2/P3/P4", verde = pe$verde, intermitente = pe$intermitente,
                                    vermelho = p$ciclo - pe$verde - pe$intermitente)
    }
    plano
  })
  de <- sprintf("%02d", est$estagio)
  para <- sprintf("%02d", c(est$estagio[-1], est$estagio[1]))
  ent <- ifelse(est$tipo == "veicular", est$amarelo + est$vermelho_geral, est$intermitente + est$vermelho_geral)
  minimos <- data.frame(grupo = link_estagio,
                        verde = sapply(est$estagio[est$tipo == "veicular"], function(e) max(g$verde_seg[g$estagio == e])))
  if (any(est$tipo == "pedestre")) minimos <- rbind(minimos, data.frame(grupo = "P1/P2/P3/P4", verde = est$verde_ped[est$tipo == "pedestre"]))
  desc_est <- sapply(seq_len(nrow(est)), function(k) {
    if (est$tipo[k] == "pedestre") return(paste0("Estágio ", est$estagio[k], ": pedestres"))
    paste0("Estágio ", est$estagio[k], ": ", sub(",.*", "", g$descricao[g$estagio == est$estagio[k]][1]))
  })
  list(
    cabecalho = list(subarea = "ISOLADO", semaforo = cruz$semaforo %||% "9000", cruzamento = toupper(sub(" \\(.*", "", cruz$nome)),
                     versao = if (is.null(cruz$semaforo)) "A" else "app", controlador = cruz$controlador %||% "—", estagios = desc_est,
                     obs = cruz$obs %||% paste0("Cruzamento fictício gerado pelo app (semente ", cruz$semente, "). Tempos calculados por Webster (MBST Vol. V, §5.9.2)."),
                     fonte = "Modelo didático inspirado na planilha de programação da AMC/CTAFOR"),
    horarios = data.frame(plano = sapply(planos, `[[`, "plano"), ciclo = sapply(planos, `[[`, "ciclo"),
                          seg_sex = sapply(planos, `[[`, "inicio"), sab = "-", dom = "-"),
    planos = planos_f,
    rodape = list(links = data.frame(link = c(g$grupo, if (any(est$tipo == "pedestre")) "P1/P2/P3/P4"),
                                     descricao = c(sub(",.*", "", g$descricao), if (any(est$tipo == "pedestre")) "Travessia de pedestres"),
                                     aproximacao = c(g$aproximacao, if (any(est$tipo == "pedestre")) "")),
                  entreverdes = data.frame(de = de, para = para, tempo = ent),
                  verdes_minimos = minimos, ciclo_max = ciclo_max)
  )
}

# HTML da ficha, para a aba do app e para baixar.
tabela_html <- function(df, cab) {
  htmltools::tags$table(class = "ficha-tab",
    htmltools::tags$tr(lapply(cab, htmltools::tags$th)),
    lapply(seq_len(nrow(df)), function(i) htmltools::tags$tr(lapply(df[i, ], function(v) htmltools::tags$td(as.character(v))))))
}

ficha_html <- function(f) {
  h <- f$cabecalho
  bloco_plano <- function(p) {
    htmltools::div(class = "ficha-plano",
      htmltools::div(class = "ficha-plano-tit", paste0("PLANO ", p$plano, " · ciclo ", p$ciclo, " s")),
      tabela_html(p$links, c("Links", "Verde", "Amarelo", "V. geral", "Vermelho")),
      if (!is.null(p$pedestres)) tabela_html(p$pedestres, c("Pedestres", "Verde", "Verm. interm.", "Vermelho")),
      htmltools::div(class = "ficha-inst", paste(paste0(names(p$instantes), ": ", p$instantes), collapse = " · ")))
  }
  htmltools::div(class = "ficha",
    htmltools::div(class = "ficha-titulo", "Planilha de Programação Semafórica"),
    htmltools::div(class = "ficha-id", paste0("Sub-área: ", h$subarea, " · Semáforo: ", h$semaforo, " · Cruzamento: ", h$cruzamento, " · Versão: ", h$versao)),
    htmltools::div(class = "ficha-sec", "CABEÇALHO"),
    htmltools::div(class = "ficha-linha",
      htmltools::div(tabela_html(f$horarios, c("Plano", "Ciclo (s)", "Seg-Sex", "Sáb", "Dom"))),
      htmltools::div(htmltools::tags$b("Estágios"), htmltools::tags$ul(lapply(h$estagios, htmltools::tags$li)),
                     htmltools::tags$p(htmltools::tags$b("Controlador: "), h$controlador),
                     htmltools::tags$p(class = "ficha-obs", htmltools::tags$b("Obs.: "), h$obs))),
    htmltools::div(class = "ficha-sec", "PLANOS SEMAFÓRICOS"),
    htmltools::div(class = "ficha-grade", lapply(f$planos, bloco_plano)),
    htmltools::div(class = "ficha-sec", "RODAPÉ"),
    htmltools::div(class = "ficha-linha",
      htmltools::div(tabela_html(f$rodape$links, c("Link", "Descrição", "Aproximação"))),
      htmltools::div(tabela_html(f$rodape$entreverdes, c("Do estágio", "Para o estágio", "Entreverdes (s)"))),
      htmltools::div(tabela_html(f$rodape$verdes_minimos, c("Grupo", "Verde mínimo (s)")),
                     htmltools::tags$p(htmltools::tags$b("Ciclo máximo: "), f$rodape$ciclo_max, " s"))),
    htmltools::div(class = "ficha-fonte", h$fonte))
}

css_ficha <- "
.ficha{font-family:Arial,sans-serif;font-size:13px;color:#141414;border:2px solid #141414;padding:14px;background:#fff}
.ficha-titulo{font-size:20px;font-weight:bold;text-align:center}
.ficha-id{text-align:center;margin-bottom:8px;color:#5c6068}
.ficha-sec{background:#049147;color:#fff;font-weight:bold;letter-spacing:2px;padding:3px 8px;margin:10px 0 6px}
.ficha-linha{display:flex;gap:18px;flex-wrap:wrap;align-items:flex-start}
.ficha-grade{display:grid;grid-template-columns:repeat(auto-fill,minmax(330px,1fr));gap:10px}
.ficha-plano{border:1px solid #141414;padding:6px}
.ficha-plano-tit{font-weight:bold;margin-bottom:4px}
.ficha-tab{border-collapse:collapse;margin-bottom:4px}
.ficha-tab th,.ficha-tab td{border:1px solid #141414;padding:2px 6px;text-align:center}
.ficha-tab th{background:#f3f4f6}
.ficha-inst{color:#049147;font-weight:bold}
.ficha-obs{max-width:420px}
.ficha-fonte{margin-top:8px;font-style:italic;color:#6b7079}
"
